 pgNew:()=>pgForm(),pgOpen:v=>{S.preg=v;ctGo();},pgBack:()=>{S.preg=null;ctGo();},
  pgF:v=>{S.pgf=v;S.pgv=null;ctRe();},pgV:v=>{S.pgv=S.pgv===v?null:v;S.pgf='todas';ctRe();},
